import sys

MOD = 10**9 + 7

def count_ways(words):
    def remove_one_letter(word):
        return [word[:i] + word[i+1:] for i in range(len(word))]

    def dp(i, prev):
        if i == len(words):
            return 1
        if (i, prev) in memo:
            return memo[(i, prev)]

        current_word = words[i]
        possible_words = set(remove_one_letter(current_word))
        valid_ways = 0

        for word in possible_words:
            if word >= prev:
                valid_ways = (valid_ways + dp(i + 1, word)) % MOD

        memo[(i, prev)] = valid_ways
        return valid_ways

    memo = {}
    return dp(0, "")

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    words = input[1:]
    result = count_ways(words)
    print(result)

if __name__ == "__main__":
    main()
